func:
const file = msg.payload;

return {
    _msgid:     msg._msgid,
    _dl:        msg._dl,
    parts:      msg.parts,
    metadata:   msg.metadata,
    _file_meta: {
        url:  file.url,
        name: file.name || "attachment",
        type: file.type || "application/octet-stream",
        size: file.size || 0
    },
    url:   file.url,
    topic: msg.topic
};

/**
 * Node-RED HTTP request node places response headers in msg.headers.
 * Resolves actual Content-Type and filename and writes into _file_meta.
 */
const headers = msg.headers || {};

node.warn("response headers: " + JSON.stringify(headers));

const raw_ct      = headers['content-type'] || headers['Content-Type'] || msg._file_meta.type;
const actual_type = raw_ct.split(";")[0].trim();

let actual_name   = msg._file_meta.name;
const disposition = headers['content-disposition'] || headers['Content-Disposition'] || "";
const cd_match    = disposition.match(/filename\*?=['"]?(?:UTF-8'')?([^;'"\r\n]+)/i);

if (cd_match) {
    actual_name = decodeURIComponent(cd_match[1].trim());
} else if (!actual_name.includes(".")) {
    const ext_map = {
        "image/jpeg":      ".jpg",
        "image/png":       ".png",
        "image/gif":       ".gif",
        "image/webp":      ".webp",
        "application/pdf": ".pdf",
        "video/mp4":       ".mp4"
    };
    actual_name = actual_name + (ext_map[actual_type] || "");
}

if (actual_type === "application/octet-stream") {
    const ext_from_name = actual_name.split(".").pop().toLowerCase();
    const name_map = {
        "jpg":  "image/jpeg",
        "jpeg": "image/jpeg",
        "png":  "image/png",
        "gif":  "image/gif",
        "webp": "image/webp",
        "pdf":  "application/pdf",
        "mp4":  "video/mp4"
    };
    if (name_map[ext_from_name]) {
        msg._file_meta.type = name_map[ext_from_name];
    }
}


msg._file_meta.name = actual_name;

node.warn("resolved: " + actual_name + " / " + actual_type);

return msg;
